mapper.select:
select count(*) from talent_job_posting
where batch_date = ''

    and job_family = #{jobFamily}

select count(*) from talent_job_posting
where batch_date <> ''

    and job_family = #{jobFamily}

select count(*) from talent_job_posting p
where 1 = 1

    and p.job_family = #{jobFamily}


    and p.batch_date = #{batchDate}

select count(distinct s.skill_name)
from talent_job_skill s
join talent_job_posting p on p.id = s.posting_id
where 1 = 1

    and s.batch_date = #{batchDate} and p.batch_date = #{batchDate}


    and p.job_family = #{jobFamily}

select p.job_family as jobFamily, group_concat(distinct p.industry order by p.industry separator '、') as industry, (select group_concat(m.major_name separator '、') from talent_major m where m.job_family = p.job_family) as majorName, count(*) as jobCount from talent_job_posting p where p.job_family is not null and p.job_family <> ''
and p.batch_date = #{batchDate}
group by p.job_family order by jobCount desc

select p.industry as industry, count(*) as jobCount, count(distinct p.job_family) as familyCount from talent_job_posting p where p.industry is not null and p.industry <> ''
and p.batch_date = #{batchDate}
group by p.industry order by jobCount desc

select batch_date as batchDate, count(*) as jobCount from talent_job_posting where batch_date <> ''
and job_family = #{jobFamily}
group by batch_date order by batch_date

select s.skill_name as skillName,
       max(s.skill_category) as skillCategory,
       count(distinct s.posting_id) as jobCount
from talent_job_skill s
join talent_job_posting p on p.id = s.posting_id
where 1 = 1

    and s.batch_date = #{batchDate} and p.batch_date = #{batchDate}


    and p.job_family = #{jobFamily}


    and s.skill_category = #{category}

group by s.skill_name
order by jobCount desc, s.skill_name
limit #{limit}

select s.skill_category as name, count(*) as value from talent_job_skill s join talent_job_posting p on p.id = s.posting_id where s.skill_category <> ''
and s.batch_date = #{batchDate} and p.batch_date = #{batchDate}
and p.job_family = #{jobFamily}
group by s.skill_category order by value desc

select s.batch_date as batchDate, s.skill_name as skillName, count(distinct s.posting_id) as jobCount from talent_job_skill s join talent_job_posting p on p.id = s.posting_id where s.batch_date <> '' and p.batch_date = s.batch_date and s.skill_name in
#{skill}
and p.job_family = #{jobFamily}
group by s.batch_date, s.skill_name order by s.batch_date

select date_format(p.create_time, '%Y-%m-%d') as batchDate, count(*) as jobCount from talent_job_posting p where p.batch_date = ''
and p.job_family = #{jobFamily}
group by date_format(p.create_time, '%Y-%m-%d') order by batchDate

select date_format(p.create_time, '%Y-%m-%d') as batchDate, s.skill_name as skillName, count(distinct s.posting_id) as jobCount from talent_job_skill s join talent_job_posting p on p.id = s.posting_id where p.batch_date = '' and s.batch_date = '' and s.skill_name in
#{skill}
and p.job_family = #{jobFamily}
group by date_format(p.create_time, '%Y-%m-%d'), s.skill_name order by batchDate

select p.job_family as jobFamily, count(*) as jobCount from talent_job_posting p where p.job_family is not null and p.job_family <> '' and not exists (select 1 from talent_major m where m.job_family = p.job_family)
and p.batch_date = #{batchDate}
group by p.job_family order by jobCount desc

mapper.delete:
delete from talent_job_skill
where posting_id in (
    select id from talent_job_posting
    where source = #{source} and batch_date = #{batchDate}
)
